from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares

def trans(x,y,z):
 t=np.eye(4);t[:3,3]=[x,y,z];return t

def rx(a):
 t=np.eye(4);t[:3,:3]=Rotation.from_rotvec([a,0,0]).as_matrix();return t

def rz(a):
 t=np.eye(4);t[:3,:3]=Rotation.from_rotvec([0,0,a]).as_matrix();return t

# Franka Panda nominal serial-chain geometry.
def fk(q):
 t=np.eye(4)
 for a,alpha,d,theta in zip([0,0,0,.0825,-.0825,0,.088],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2],[.333,0,.316,0,.384,0,0],q):
  t=t@trans(a,0,0)@rx(alpha)@trans(0,0,d)@rz(theta)
 return t@trans(0,0,.107)

def grip_fk(q):
 t=fk(q);t[:3,3]+=.1*t[:3,2];return t

class ArmIK:
 def __init__(self,s):
  self.ref=np.array(s)
  self.yaw=float(s[2])
  self.rotation=Rotation.from_rotvec([0,0,self.yaw]).as_matrix()
  self.origin=np.array(s[26:29])-self.rotation@grip_fk(s[4:11])[:3,3]
 def transform(self,q):
  t=grip_fk(q);t[:3,3]=self.origin+self.rotation@t[:3,3];t[:3,:3]=self.rotation@t[:3,:3];return t
 def solve(self,p,R=None,q=None):
  q0=self.ref[4:11] if q is None else np.array(q)
  def err(v):
   t=self.transform(v)
   out=list((t[:3,3]-p)*3)
   if R is not None:out+=list(Rotation.from_matrix(R.T@t[:3,:3]).as_rotvec())
   out+=list(.015*(v-q0))
   return out
  lo=np.array([-2.89,-1.75,-2.89,-3.06,-2.89,-.01,-2.89]);hi=np.array([2.89,1.75,2.89,-.07,2.89,3.75,2.89])
  best=least_squares(err,np.clip(q0,lo+1e-4,hi-1e-4),bounds=(lo,hi),max_nfev=250)
  return best.x, np.linalg.norm(self.transform(best.x)[:3,3]-p)
